"""Comprehensive verification that shell completion no longer leaks file handles."""
import gc
import os
import tempfile
import warnings

import click
from click.shell_completion import ShellComplete
from click.types import File


def get_completions(cli, args, incomplete):
    comp = ShellComplete(cli, {}, cli.name, "_CLICK_COMPLETE")
    return comp.get_completions(args, incomplete)


def count_resource_warnings(run):
    with warnings.catch_warnings(record=True) as caught:
        warnings.simplefilter("always")
        run()
        gc.collect()
    return sum(1 for w in caught if issubclass(w.category, ResourceWarning))


tmp_path = tempfile.NamedTemporaryFile(delete=False, suffix=".txt").name
with open(tmp_path, "w") as fh:
    fh.write("hello")

results = {}

# 1. Plain command with a file option (value completed)
@click.command()
@click.option("-f", type=File())
def cli(f):
    pass

results["command_file_option"] = count_resource_warnings(
    lambda: get_completions(cli, ["-f", tmp_path], "")
)

# 2. Group with a file option on the group, completing a subcommand
@click.group()
@click.option("-f", type=File())
def grp(f):
    pass


@grp.command()
@click.option("-x", type=File())
def sub(x):
    pass

results["group_file_option_subcommand"] = count_resource_warnings(
    lambda: get_completions(grp, ["-f", tmp_path, "sub"], "")
)

# 3. Group with file option on subcommand
results["group_subcommand_file_option"] = count_resource_warnings(
    lambda: get_completions(grp, ["sub", "-x", tmp_path], "")
)

# 4. Chained group with file options
@click.group(chain=True)
@click.option("-f", type=File())
def chain_cli(f):
    pass


@chain_cli.command()
@click.option("-a", type=File())
def set_cmd(a):
    pass


@chain_cli.command()
def start_cmd():
    pass

results["chained_file_option"] = count_resource_warnings(
    lambda: get_completions(chain_cli, ["-f", tmp_path, "set_cmd", "-a", tmp_path], "")
)

results["chained_multiple"] = count_resource_warnings(
    lambda: get_completions(chain_cli, ["set_cmd", "-a", tmp_path, "start_cmd"], "")
)

# 5. Argument file type (nargs)
@click.command()
@click.argument("data", type=File())
def arg_cli(data):
    pass

results["argument_file"] = count_resource_warnings(
    lambda: get_completions(arg_cli, [tmp_path], "")
)

os.unlink(tmp_path)

print("ResourceWarning counts after fix (all should be 0):")
for name, count in results.items():
    status = "OK" if count == 0 else "LEAK"
    print(f"  {name}: {count} ({status})")

all_ok = all(c == 0 for c in results.values())
print("\nRESULT:", "PASS - no leaks" if all_ok else "FAIL - leaks detected")
